node <<'NODE'
const fs=require("fs"), path=require("path"), crypto=require("crypto");
const base="docs/papers211_215_sequence/scouting/finite_nonlinear_residual_desk01";
const expected=["HANDOFF.md","INPUT_PINS.sha256","LOCAL_NATIVE_RECORDS.json","PRIMARY_SOURCE_RECORDS.json","PROOF_PACKAGE.md","SOURCES_AND_SUBTRACTION.md"].sort();
const ensure=(x,m)=>{if(!x)throw new Error(m);};
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const actual=fs.readdirSync(base).sort();
ensure(JSON.stringify(actual)===JSON.stringify(expected),"unexpected initial payload");
const pins=fs.readFileSync(path.join(base,"INPUT_PINS.sha256"),"utf8");
ensure(pins.endsWith("\n"),"pin file missing LF");
const rows=pins.trimEnd().split("\n");
ensure(rows.length===11,"not 11 pins");
const pinChecks=[];
for(const line of rows){
 const m=/^([0-9a-f]{64})  (docs\/.+)$/.exec(line); ensure(m,"bad pin line");
 ensure(!/\/(?:qa|reviews?|frozen[^/]*|[Rr]ound[^/]*)\//.test(m[2]),"unexpected pinned path");
 ensure(sha(fs.readFileSync(m[2]))===m[1],"pin changed: "+m[2]);
 pinChecks.push(m[2]);
}
const native=JSON.parse(fs.readFileSync(path.join(base,"LOCAL_NATIVE_RECORDS.json"),"utf8"));
const primary=JSON.parse(fs.readFileSync(path.join(base,"PRIMARY_SOURCE_RECORDS.json"),"utf8"));
ensure(native.records.length===27,"native count");
ensure(primary.browser_requests.length===6,"browser request count");
ensure(native.records[21].output===pins&&native.records[26].output===pins,"native pins differ");
let fullReadComparisons=0;
for(const r of native.records){
 const m=/^sed -n '(\d+),(\d+)p' (.+)$/.exec(r.cmd||"");
 if(m){
  const raw=fs.readFileSync(m[3],"utf8");
  const lines=raw.match(/[^\n]*\n|[^\n]+$/g)||[];
  const excerpt=lines.slice(Number(m[1])-1,Number(m[2])).join("");
  ensure(Buffer.from(excerpt).equals(Buffer.from(r.output)),"excerpt bytes differ record "+r.record_index);
  fullReadComparisons++;
 }
 if(![17,19].includes(r.record_index))ensure(r.exit_code===0,"unexpected recorded exit "+r.record_index);
}
for(const [launch,completion] of [[17,18],[19,20]]){
 const a=native.records[launch],b=native.records[completion];
 ensure(a.session_id===b.poll.session_id&&b.exit_code===0,"stream completion binding");
 ensure(b.output_not_archived&&!Object.hasOwn(b,"output"),"public body archive boundary");
}
let links=0;const external=[];
for(const name of expected.filter(n=>n.endsWith(".md"))){
 const txt=fs.readFileSync(path.join(base,name),"utf8");
 ensure(txt.endsWith("\n"),"markdown missing LF");
 for(const m of txt.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){
  const target=m[1];if(/^https?:/.test(target)){external.push(target);continue;}
  ensure(fs.existsSync(path.resolve(base,target.split("#")[0])),"missing local link "+target);links++;
 }
}
const result={status:"DOCUMENTARY_ONLY_PASS",science_executed:false,initial_payload_files:expected.length,historical_pins:pinChecks.length,exact_native_excerpt_byte_comparisons:fullReadComparisons,local_markdown_links:links,browser_request_records:primary.browser_requests.length,completed_source_streams:2,source_full_bodies_archived:false,payloads:expected.map(name=>{const b=fs.readFileSync(path.join(base,name));return {path:name,bytes:b.length,sha256:sha(b)};}),external_urls:external};
process.stdout.write(JSON.stringify(result,null,2)+"\n");
NODE
